// How the front side decides what to tell the person today. The structure is the team's: one dated
// message about the body and the psyche, a short explanation, buttons, a choice; critical and not critical,
// light and heavier situations; tell only when something is really wrong. The levels follow NASA's alert
// levels (NASA-STD-3001 Vol 2 Rev F). The working-out of the variants and every threshold below is
// Claude's, at the team's request, and is marked as such on the page: the thresholds are placeholders
// until the team sets them. Code generated by Claude (Anthropic), an AI system.
//
// Safety and calm (drafts by Claude after the NASA-style reviews of 15 Nov 2026, for the team and flight
// surgeons to decide):
// - one reading past a published red limit (config.js, "red") raises its level at once, with no streak;
// - a change that flight studies call common in flight, inside the band its study supports, is information
//   on the measure's page and never raises the headline; a fever is never explained away that way;
// - a daily vital just outside the norm (inside its red limits) needs a few readings in a row before "attention",
//   unless its run holds a reading past a red limit, or two or more vital signs are outside the norm at once;
// - a reading taken during exercise that is only recorded never changes the judgement of the person at rest;
// - the straight-line forecast alerts only for slow measures, or when the line clearly outruns the daily scatter;
// - with no fresh data the message does not say "excellent";
// - a cabin value past the ship's own limit reaches the person's message as a ship alarm;
// - "I am okay" after a camera or Help key alarm calls the alarm off (the record stays).
// Drafts by Claude after the final reviews of 15 Nov 2026 (the team and flight surgeons decide): what the person logs
// or answers can say "tell someone", as an "attention" item of kind 'tell' that never goes beyond the person's own
// screen by itself: an eye self-check answer other than "no change", until a later "no change"; a symptom rated
// RULES.symptomTellAt or more in the last RULES.symptomHours hours; a medicine past the kit list's own printed rules.
import { isLowEnergy } from './fatigue.js';
import { STATUS } from './engine.js';
import { forecast } from './trend.js';
import { KIT_HOURS, gmtText, kitFindings, kitFindingShort, kitFindingText, logText } from './quicklog.js';

export const LEVEL = { FINE: 0, ATTENTION: 1, ACTION: 2, URGENT: 3 };
export const LEVEL_WORD = ['fine', 'attention', 'needs action', 'urgent'];
// The words used for the levels of the red limits in config.js.
export const RED_LEVEL = { action: LEVEL.ACTION, urgent: LEVEL.URGENT };

// Changes that published flight studies describe as common in flight, each bounded by what its study supports.
// Inside the band the reading is shown on the measure's page as "common in flight" (level fine); outside the
// band, or past a red limit, it is judged like any other reading. Drafts: the flight surgeons decide.
export const EXPECTED = {
  temp: {
    side: 'above',
    rise: 1.0, // °C: resting core temperature about 1.01 °C above the pre-flight level (Stahn et al., 2017)
    rampDays: 75, // the rise builds up gradually and levels off after about 75 days of flight (Stahn et al., 2017)
    below: 38.0, // the band always ends below the fever line of 38.0 °C (CDC): a fever is never "common in flight"
    text: 'In flight, resting body temperature rises gradually by about 1 °C over two and a half months (Stahn et al., 2017). Above the usual range on Earth, a reading up to that rise and below 38.0 °C counts as this change; 38.0 °C or more is a fever (CDC) and never counts as it.',
    source: 'Stahn et al., 2017', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5701078/',
    source2: 'CDC', url2: 'https://www.cdc.gov/quarantine/maritime/definitions-signs-symptoms-conditions-ill-travelers.html',
    draft: true,
  },
  sleep: {
    side: 'below',
    atLeast: 5.0, // hours: on the ISS 58% of nights were 5 to under 7 hours (Barger et al., 2014, Table 2)
    text: 'On the ISS, astronauts slept about 6 hours a night on average (6.09 hours, SD 0.67), and 58% of nights were 5 to under 7 hours (Barger et al., 2014). Here 5 hours or more counts as this change; less than 5 hours does not.',
    source: 'Barger et al., 2014', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4188436/',
    draft: true,
  },
};

// How often a measure is expected, in days; after RULES.staleAfter times that without a reading the data counts
// as stale. This is a draft of the medical plan: on the ISS many vitals come from periodic exams and wearables,
// so the flight surgeons set the real cadence. Mood and energy are the daily check-in.
export const EXPECTED_EVERY_DAYS = { pulse: 1, bp: 1, temp: 1, sleep: 1, resp: 1, fluid: 1, radiation: 1, co2: 1, cabinTemp: 1, cabinO2: 1, cabinPressure: 1, vo2max: 30, mood: 1, attitude: 1 };

// Measures that change slowly over weeks: only these get a forecast alert from the straight line (the reviews of
// 15 Nov 2026). Daily vitals scatter from day to day, and a straight line through them misleads. Body mass is not
// one of them since it has a band (config.js): in ISS data crew lost 2 to 5% in the first month and then kept the
// lower mass (NASA HRP nutrition report, 2015), so a straight line through the flight would overstate the loss; it
// still gets a forecast when its line clearly outruns the scatter (RULES.trendOverNoise).
export const SLOW_MEASURES = ['vo2max', 'strength', 'radiation', 'hearing'];

// The vital signs that NEWS2 scores (RCP, 2017): breathing rate, blood oxygen, systolic pressure, pulse, temperature.
export const VITAL_SIGNS = ['resp', 'spo2', 'bp', 'pulse', 'temp'];

// Placeholder thresholds (Claude's), shown on the page as such.
export const RULES = {
  outStreakForAttention: 3, // draft: a daily vital outside the norm, inside its red limits: this many readings in a row for "attention"
  outStreakForActionDaily: 7, // draft: ... this many in a row (a week of daily readings): "needs action"
  outStreakForAction: 3, // a measure taken less often than daily: this many readings in a row outside the norm: "needs action"
  staleAfter: 2, // a measure is stale after this many times its expected interval without a reading
  trendOverNoise: 1, // draft: for a daily vital, the line must move more in one day than the readings scatter around it
  trendMinDays: 7, // draft: ... and needs in-flight readings on at least this many days, since a few points can look steep
  vitalsTogether: 2, // draft: this many vital signs outside the norm at the same time count at once, with no repeat
  togetherHours: 24, // draft: ... "at the same time": the last reading of each within this many hours of now
  psycheDays: 14, // the self-reports of this many last days are looked at
  badDaysForAttention: 6, // draft: bad mood or low energy on this many of those days: "attention" (was 3, which fired on 39 to 56% of days for people with no mood problem)
  badDaysForAction: 8, // draft: ... on this many, more than half of the days: "needs action" (was 6)
  cameraHours: 24, // a camera alarm in this many last hours makes the body "urgent", unless "I am okay" came after it
  symptomTellAt: 8, // draft: a symptom rated this or more of 10 ...
  symptomHours: 24, // ... logged in this many last hours: "attention", with the advice to tell the crew medical officer
  kitNightHours: 12, // draft: "one night" for the kit list's "Do not use with (other) sleep meds": two medicines this many hours apart or less
};

// Why the draft rules above exist, for the page. The red limits carry their own sources (config.js, "red").
export const RULE_NOTES = {
  outStreakForAttention: {
    text: 'A daily vital just outside the norm becomes "attention" only when it stays outside: in hospitals an estimated 85 to 99% of alarm signals need no clinical intervention, for example when the default limits are not adjusted to the person. One reading past a red limit still counts at once, and a run outside the norm that holds one is never waited on.',
    source: 'The Joint Commission, Sentinel Event Alert 50, 2013', url: 'https://digitalassets.jointcommission.org/api/public/content/f65e5c9df2b94000a99445e0a7877007', draft: true,
  },
  staleAfter: {
    text: 'Stale or missing data must be shown as such, so with no fresh data the message never says "excellent".',
    source: 'NASA-STD-3001 Vol 2 Rev F [V2 10020]', url: 'https://standards.nasa.gov/system/files/tmp/NASA-STD-3001%20Vol%202%20Rev%20F.pdf', draft: true,
  },
  vitalsTogether: {
    text: 'Two or more vital signs outside the norm at the same time count at once, without waiting for a repeat: NEWS2 notes that a disturbance of one measure rarely comes alone, and that several disturbed together are a more robust sign of acute illness than any single one.',
    source: 'RCP NEWS2, 2017 (PDF page 38)', url: 'https://www.rcp.ac.uk/media/a4ibkkbf/news2-final-report_0_0.pdf', draft: true,
  },
  trendOverNoise: {
    text: 'A straight line through readings that scatter from day to day misleads: a daily vital gets a forecast alert only when its line moves more in one day than the readings scatter around it, over a week or more. Slow measures always can.',
    source: "Claude's technical choice, after the team's review of 15 Nov 2026", url: null, draft: true,
  },
  badDaysForAttention: {
    text: "Placeholder until the team chooses the questionnaire and the rule (the team's open question 8).",
    source: "Claude's placeholder", url: null, draft: true,
  },
  symptomTellAt: {
    text: `Most medical problems in flight are symptoms, not numbers (NASA counted 389 reports of nasal congestion, 382 of back pain and 233 of headache up to 2006), so a strong one must not read "excellent". A symptom rated ${RULES.symptomTellAt} or more of 10 in the last ${RULES.symptomHours} hours shows as "attention" with the advice to tell the crew medical officer. The log stays private: nothing is sent unless the person chooses.`,
    source: 'NASA HRP evidence report, 2017', url: 'https://ntrs.nasa.gov/api/citations/20170004604/downloads/20170004604.pdf', draft: true,
  },
  kitNightHours: {
    text: `The kit list's own printed rules, kept as data: no more tablets every 24 hours than its limit (acetaminophen 12, ibuprofen 8), and its sleep medicines not with other sleep medicines, nor with meclizine or promethazine ("Do not use with sleep meds"). A match shows as "attention" and quotes the kit list. Two medicines count as one night when they are ${RULES.kitNightHours} hours apart or less: a draft.`,
    source: 'NASA ISS medical kit list, 9 Apr 2015', url: 'https://www.governmentattic.org/19docs/NASA-ISSmedicalEmergManual_2016.pdf', draft: true,
  },
  eyeAnswer: {
    text: 'NASA ranks distorted central vision as SANS with an acute effect on sight, a tier above clinically concerning retinal swelling. Any eye self-check answer but "No change" shows as "attention" with the advice to tell the flight surgeon, until a later "No change". Who reads these answers between the eye exams is the team\'s open decision.',
    source: 'Brunstetter et al., NASA, 2023', url: 'https://ntrs.nasa.gov/api/citations/20220014606/downloads/Brunstetter%20-%20IWS%202023%20SANS%20Clinical%20Update%20-%20Abstract%20-%2023Sep22.pdf', draft: true,
  },
};

// The ship's own readings belong to this id (config.js, SHIP).
const SHIP_DEFAULT = { id: 'ship', baselines: {} };

const DAY = 24 * 60 * 60 * 1000;
const ms = (t) => (t instanceof Date ? t.getTime() : new Date(t).getTime());

function normOf(cell, person, list = []) {
  if (cell.normType === 'range') return { min: cell.norm.min, max: cell.norm.max, maxExclusive: Boolean(cell.norm.maxExclusive) };
  if (cell.normType === 'baseline-shift') {
    // Hearing: below the person's own pre-flight test plus the shift (engine.js keeps the test on each reading after
    // launch); with no pre-flight test on record, the cell's second reference (src/nasa-rules.js says the same).
    const based = list.filter((x) => Number.isFinite(x.baseline));
    const base = based.length ? based[based.length - 1].baseline : null;
    const f = cell.norm.fallback || {};
    return base === null ? { min: null, max: f.max ?? null, maxExclusive: Boolean(f.maxExclusive) } : { min: null, max: base + cell.norm.shiftAtLeast, maxExclusive: true };
  }
  if (cell.normType === 'baseline-percent') {
    const base = person && person.baselines ? Number(person.baselines[cell.baselineKey]) : NaN;
    return Number.isFinite(base) ? { min: (base * cell.norm.minPercent) / 100, max: null } : null;
  }
  if (cell.normType === 'below-both') return { min: null, max: cell.norm.sysBelow, maxExclusive: true };
  return null;
}

const valueOf = (cell, v) => (cell.normType === 'below-both' ? Number(v && v.sys) : Number(v));

// Is this reading outside the norm only by a change that flight studies call common, inside its band?
// The temperature band grows with the flight day, as the rise does; both bands hold in flight only.
export function commonInFlight(cell, entry, norm, mission) {
  const e = EXPECTED[cell.indicator];
  if (!e || !entry || entry.status !== STATUS.OUT || entry.red || entry.side !== e.side || !norm) return false;
  const t = ms(entry.time);
  if (!(t >= ms(mission.launch) && t <= ms(mission.landing))) return false;
  const v = valueOf(cell, entry.value);
  if (e.side === 'above') {
    const grown = Math.min(1, (t - ms(mission.launch)) / DAY / e.rampDays);
    return v < e.below && v <= norm.max + e.rise * grown;
  }
  return v >= e.atLeast;
}

// How far the in-flight readings scatter around the straight line (the standard deviation of what is left).
function scatter(points, line, mission) {
  const pts = points.filter((p) => Number.isFinite(p.value) && ms(p.time) >= ms(mission.launch) && ms(p.time) <= ms(mission.landing));
  if (pts.length < 3) return null;
  const sse = pts.reduce((sum, p) => sum + (p.value - line.at(p.time)) ** 2, 0);
  return Math.sqrt(sse / (pts.length - 2));
}

// One measure of one person: the latest reading, how long it has been outside the norm, the forecast.
// streak counts the readings in a row outside the norm, back from the last one, leaving out a reading that is
// only a change common in flight (it is not a problem, so it neither starts nor lengthens a run).
// A reading taken during exercise that the machine only recorded (engine.js) says nothing about the person at
// rest, so the judgement, the run and the forecast leave it out; the age of the data still counts every reading.
// redInRun: the current run outside the norm holds a reading past a red limit. runFrom: when the run began.
export function measureState({ machine, person, cell, mission, now }) {
  const list = machine.history(person.id, cell.indicator);
  const judged = list.filter((x) => !(x.context === 'exercise' && x.status === STATUS.RECORDED));
  const latest = list[list.length - 1] || null;
  const last = judged[judged.length - 1] || null;
  const norm = normOf(cell, person, list);
  let streak = 0;
  let redInRun = false;
  for (let i = judged.length - 1; i >= 0 && judged[i].status === STATUS.OUT && !commonInFlight(cell, judged[i], norm, mission); i -= 1) {
    streak += 1;
    if (judged[i].red) redInRun = true;
  }
  const runFrom = streak ? judged[judged.length - streak].time : null;
  const side = last && last.status === STATUS.OUT ? (last.side || (cell.normType === 'below-both' ? 'above' : null)) : null;
  const points = judged.map((x) => ({ time: x.time, value: valueOf(cell, x.value) }));
  const fc = norm && cell.kind === 'number'
    ? forecast(points, { norm, flatPerDay: 0, now: mission.today, landing: mission.landing, window: { from: mission.launch, to: mission.landing } })
    : null;
  const every = EXPECTED_EVERY_DAYS[cell.indicator];
  const stale = Boolean(every && latest && ms(now) - ms(latest.time) > RULES.staleAfter * every * DAY);
  // The line "clearly" moves when it changes more in one day than the readings scatter around it, over a week or more.
  const noise = fc && fc.line ? scatter(points, fc.line, mission) : null;
  const clearTrend = Boolean(fc && fc.line && noise !== null && fc.days >= RULES.trendMinDays && Math.abs(fc.line.perDay) > RULES.trendOverNoise * noise);
  return { cell, list, last, norm, streak, redInRun, runFrom, side, forecast: fc, stale, noise, clearTrend };
}

// A forecast alert: only for a slow measure, or for a line that clearly outruns the daily scatter.
function forecastAlert(cell, m) {
  const c = m.forecast && m.forecast.crossing;
  if (!c || c.already) return false;
  return SLOW_MEASURES.includes(cell.indicator) || m.clearTrend;
}

// What the last reading of one measure means today: one item, or null when there is nothing to say.
// Items of level fine are information for the measure's page; they never change the headline.
function judge(cell, m, mission) {
  const last = m.last;
  if (last.status !== STATUS.OUT) return forecastAlert(cell, m) ? { kind: 'forecast', level: LEVEL.ATTENTION, cell, m } : null;
  if (last.red) return { kind: 'red', level: RED_LEVEL[last.red.level], cell, m, red: last.red };
  if (cell.normType === 'baseline-percent' || cell.indicator === 'radiation') return { kind: 'standard', level: LEVEL.ACTION, cell, m };
  if (commonInFlight(cell, last, m.norm, mission)) return { kind: 'expected', level: LEVEL.FINE, cell, m, expected: EXPECTED[cell.indicator] };
  const daily = EXPECTED_EVERY_DAYS[cell.indicator] === 1;
  // A run that holds a reading past a red limit is not "just outside the norm": it is never waited on.
  if (daily && m.streak < RULES.outStreakForAttention && !m.redInRun) return { kind: 'watch', level: LEVEL.FINE, cell, m, needed: RULES.outStreakForAttention };
  const forAction = daily ? RULES.outStreakForActionDaily : RULES.outStreakForAction;
  return { kind: 'out', level: m.streak >= forAction ? LEVEL.ACTION : LEVEL.ATTENTION, cell, m };
}

// Is there fresh data to judge the body and the mind? Each daily measure of the person needs a reading within
// RULES.staleAfter days, and the mind needs a daily check-in (mood or energy). A measure with no reading at all
// counts as missing too, so an empty record is never "excellent".
function freshness({ machine, person, cells, now }) {
  const missing = [];
  const lateness = (list) => {
    const last = list.length ? list[list.length - 1] : null;
    const age = last ? ms(now) - ms(last.time) : null;
    return { last: last ? last.time : null, days: age === null ? null : Math.floor(age / DAY), late: age === null || age > RULES.staleAfter * DAY };
  };
  let bodyOk = true;
  const checkins = [];
  for (const cell of cells) {
    if (EXPECTED_EVERY_DAYS[cell.indicator] !== 1 || cell.section === 'env' || cell.onlyOnEarth) continue;
    const list = machine.history(person.id, cell.indicator);
    if (cell.kind === 'self-report') { checkins.push(...list); continue; }
    if (cell.kind !== 'number') continue;
    const x = lateness(list);
    if (x.late) { bodyOk = false; missing.push({ indicator: cell.indicator, label: cell.label, last: x.last, days: x.days }); }
  }
  checkins.sort((a, b) => ms(a.time) - ms(b.time));
  const mind = lateness(checkins);
  if (mind.late) missing.push({ indicator: 'checkin', label: 'Daily check-in', last: mind.last, days: mind.days });
  return { body: bodyOk, mind: !mind.late, missing };
}

const top = (items) => items.reduce((lv, x) => Math.max(lv, x.level), LEVEL.FINE);
const HOUR = 60 * 60 * 1000;
const iso = (t) => new Date(ms(t)).toISOString();

// ---------- the person's own logs and answers that say "tell someone" (drafts) ----------
// Each gives at most one item of kind 'tell' at "attention", never higher, so it is never shared with the crew
// (crew lines carry only urgent red limits and alarms): the symptom and medicine logs stay private until the person
// chooses to send them. The item carries its own words for the screens: title, text (for Messages and the message
// to the doctor), short (one line for Today), steps (What to do), who to tell, rule, time (of the entry behind it),
// entries (the entries behind it, newest first), private, draft and source ({ name, url }).
const tellItem = (cell, fields) => ({ kind: 'tell', level: LEVEL.ATTENTION, cell, title: cell.label, private: Boolean(cell.private), draft: true, ...fields });

// The eye self-check: the latest answer, when the cell's tellDoctor lists it, until a later "no change".
function eyeItem(cell, list) {
  const tell = cell.tellDoctor;
  const last = list[list.length - 1];
  if (!tell || !Array.isArray(tell.values) || !last || !tell.values.includes(last.value)) return null;
  const answer = (cell.answers || []).find((a) => a.value === last.value) || { label: String(last.value) };
  const who = tell.who || 'flight surgeon';
  return tellItem(cell, {
    rule: 'eye-answer', who, time: iso(last.time), entries: [last], source: tell.src || null,
    text: `"${answer.label}", your eye self-check answer of ${gmtText(last.time)}. Worth telling your ${who} (a draft rule; who reads these answers between the eye exams is the team's open decision). It stays here until a later answer "No change".`,
    short: `${answer.short || answer.label}: tell your ${who}`,
    steps: [
      `You: tell your ${who}, for example with the "Message the doctor" button.`,
      'You: do the self-check again when you are ready; the answer "No change" ends this message.',
      'NASA checks the eyes on flight day 30, flight day 90 and 30 days before return.',
    ],
  });
}

// Symptoms rated RULES.symptomTellAt or more in the last RULES.symptomHours hours, newest first.
function symptomItem(cell, list, now) {
  const strong = list.filter((x) => ms(now) - ms(x.time) <= RULES.symptomHours * HOUR && x.value && Number(x.value.severity) >= RULES.symptomTellAt).reverse();
  if (!strong.length) return null;
  const shown = strong.slice(0, 3).map((x) => `${logText('symptoms', x.value)} (${gmtText(x.time)})`);
  const more = strong.length - shown.length;
  return tellItem(cell, {
    rule: 'strong-symptom', who: 'crew medical officer', time: iso(strong[0].time), entries: strong, source: null,
    text: `${shown.join('; ')}${more ? `; and ${more} more` : ''}. A symptom of ${RULES.symptomTellAt} or more of 10 in the last ${RULES.symptomHours} hours: tell the crew medical officer (a draft rule; the team decides).`,
    short: `${logText('symptoms', strong[0].value)}: tell the crew medical officer`,
    steps: [
      'You: tell the crew medical officer.',
      'You: if it is bad right now or getting worse, hold the Help key for 2 seconds.',
      'You: to tell the doctor as well, use "Message the doctor". Your log is private: it is sent only if you choose.',
    ],
  });
}

// Medicines past the kit list's own printed rules (quicklog.js kitFindings), quoting the kit list.
function medicineItem(cell, list, now) {
  const found = kitFindings(list, { now, nightHours: RULES.kitNightHours, cell });
  if (!found.length) return null;
  const involved = new Set(found.flatMap((f) => (f.rule === 'max' ? [f.medicine] : f.medicines)));
  return tellItem(cell, {
    rule: 'kit', who: 'crew medical officer', time: found[0].time, findings: found, source: cell.kitSrc || null,
    entries: list.filter((x) => x.value && involved.has(x.value.medicine) && ms(now) - ms(x.time) <= (KIT_HOURS + RULES.kitNightHours) * HOUR).reverse(),
    text: `${found.map((f) => kitFindingText(f, cell)).join(' ')} Tell the crew medical officer, or your flight surgeon (a draft rule from the kit list of 2015; the flight surgeons set the real one).`,
    short: found.map((f) => kitFindingShort(f, cell)).join('; '),
    steps: [
      'You: tell the crew medical officer, or your flight surgeon with the "Message the doctor" button.',
      "You: the kit list's own words are quoted above; the flight surgeons own the real list and its rules.",
      'Your log is private: it is sent only if you choose.',
    ],
  });
}

function tellItems({ machine, person, cells, now }) {
  const out = [];
  const rules = { visionCheck: (c, list) => eyeItem(c, list), symptoms: (c, list) => symptomItem(c, list, now), medicines: (c, list) => medicineItem(c, list, now) };
  for (const cell of cells) {
    if (!rules[cell.indicator] || cell.onlyOnEarth) continue;
    const it = rules[cell.indicator](cell, machine.history(person.id, cell.indicator));
    if (it) out.push(it);
  }
  return out;
}

// Everything the front side needs for one person today.
// body, psyche: the levels and items of the headline; an item counted at once because several vital signs are
// outside the norm together carries `together` (their indicators). Item kinds: camera, red, standard, out, tell (the
// person's own log or answer says to tell someone; it carries its own title, text, short and steps), forecast, mood.
// info: level-fine notes for the measures' pages ('stale', 'expected' = common in flight, 'watch' = outside the norm
// once, waiting for a repeat, 'camera-cleared' = "I am okay" called off a camera or Help key alarm).
// fresh: whether there is fresh data to judge the body and the mind. ship: cabin values past the ship's own
// limits, which reach every person. doctorReachable: a doctor on board, or a link to Earth.
export function assess({ machine, person, cells, mission, now, ship = SHIP_DEFAULT }) {
  const body = [];
  const psyche = [];
  const info = [];
  const judged = [];
  for (const cell of cells) {
    if (cell.section === 'env' || cell.kind !== 'number' || cell.onlyOnEarth) continue;
    const m = measureState({ machine, person, cell, mission, now });
    if (!m.last) continue;
    if (m.stale) info.push({ kind: 'stale', level: LEVEL.FINE, cell, m });
    const it = judge(cell, m, mission);
    if (it) judged.push(it);
  }
  // Several vital signs outside the norm at the same time are not waited on (draft, RULE_NOTES.vitalsTogether):
  // a watched one counts at once, as "attention".
  const outNow = judged.filter((x) => VITAL_SIGNS.includes(x.cell.indicator) && ['watch', 'out', 'red'].includes(x.kind)
    && ms(now) - ms(x.m.last.time) <= RULES.togetherHours * 60 * 60 * 1000);
  const together = [...new Set(outNow.map((x) => x.cell.indicator))];
  for (const x of judged) {
    const it = x.kind === 'watch' && together.length >= RULES.vitalsTogether && together.includes(x.cell.indicator)
      ? { kind: 'out', level: LEVEL.ATTENTION, cell: x.cell, m: x.m, together } : x;
    (it.level > LEVEL.FINE ? body : info).push(it);
  }

  // Camera: an alarm after the question "Are you okay?" (or from the Help key) makes the body "urgent", until a later
  // "I am okay" calls it off: an answer whose camera trigger says clears (config.js), from the question or from
  // "I am okay: false alarm". The alarm stays in the record, and info gets a 'camera-cleared' note. The camera's
  // history is in time order, so "later" is later in the list; "asleep" calls nothing off.
  const camCell = cells.find((c) => c.indicator === 'camera');
  const clears = new Set(Object.entries((camCell && camCell.triggers) || {}).filter(([, t]) => t.clears).map(([value]) => value));
  let alarm = null;
  let cleared = null;
  for (const x of machine.history(person.id, 'camera')) {
    if (ms(now) - ms(x.time) > RULES.cameraHours * HOUR) continue;
    if (x.status === STATUS.OUT) { alarm = x; cleared = null; } else if (alarm && !cleared && clears.has(x.value)) cleared = x;
  }
  if (alarm && !cleared) body.push({ kind: 'camera', level: LEVEL.URGENT, time: alarm.time, value: alarm.value });
  if (alarm && cleared) info.push({ kind: 'camera-cleared', level: LEVEL.FINE, time: cleared.time, value: cleared.value, source: cleared.source, alarm: { time: alarm.time, value: alarm.value, source: alarm.source } });

  // What the person logged or answered that says "tell someone" (drafts): see tellItems.
  body.push(...tellItems({ machine, person, cells, now }));

  // Mind: bad mood or low energy on several of the last days (placeholder rule until the team sets one).
  const since = ms(now) - RULES.psycheDays * DAY;
  const badDays = new Set();
  // A low day: mood "bad", or energy at step FATIGUE_RULE.lowFrom or more of the Samn-Perelli scale (src/fatigue.js).
  for (const [indicator, low] of [['mood', (v) => v === 'bad'], ['attitude', isLowEnergy]]) {
    for (const x of machine.history(person.id, indicator)) {
      if (ms(x.time) >= since && low(x.value)) badDays.add(new Date(x.time).toISOString().slice(0, 10));
    }
  }
  if (badDays.size >= RULES.badDaysForAttention) {
    psyche.push({ kind: 'mood', level: badDays.size >= RULES.badDaysForAction ? LEVEL.ACTION : LEVEL.ATTENTION, days: badDays.size });
  }
  const rank = { camera: 0, red: 1, standard: 2, out: 3, tell: 4, forecast: 5, mood: 6 };
  const order = (a, b) => b.level - a.level || rank[a.kind] - rank[b.kind];
  body.sort(order);
  psyche.sort(order);

  // The ship's alarms reach every person: only cabin values past the ship's own (red) limits.
  const shipItems = assessShip({ machine, ship, cells, mission, now }).items.filter((x) => x.kind === 'red');
  const st = typeof machine.getState === 'function' ? machine.getState() : {};
  return {
    body: { level: top(body), items: body },
    psyche: { level: top(psyche), items: psyche },
    info,
    fresh: freshness({ machine, person, cells, now }),
    ship: { level: top(shipItems), items: shipItems },
    doctorReachable: Boolean(st.doctorOnBoard) || st.linkToEarth !== false,
  };
}

// The ship's own measures (cabin air), the same way, for the status bar. A value past the ship's own limit
// (config.js, "red") takes that limit's level; any other value outside the norm is "attention".
export function assessShip({ machine, ship, cells, mission, now }) {
  const items = [];
  for (const cell of cells) {
    if (cell.section !== 'env') continue;
    const m = measureState({ machine, person: ship, cell, mission, now });
    if (!m.last || m.last.status !== STATUS.OUT) continue;
    const red = m.last.red;
    items.push(red ? { kind: 'red', level: RED_LEVEL[red.level], cell, m, red } : { kind: 'out', level: LEVEL.ATTENTION, cell, m });
  }
  items.sort((a, b) => b.level - a.level);
  return { level: top(items), items };
}

// The highest level of the day for the card's colour: body, mind or ship.
export const topLevel = (a) => Math.max(a.body.level, a.psyche.level, a.ship ? a.ship.level : LEVEL.FINE);

// The dated message in the team's own words (translated from Russian), for example
// "As of 14 Nov 2026, your physical and mental condition is excellent. Keep it up, well done!"
// The team's wording stays for every existing state. Drafts by Claude at the team's request, marked on the page:
// with no fresh data a side is "not enough fresh data to judge", never "excellent"; a ship alarm comes first;
// with no doctor on board and no link, "urgent" says the crew has been alerted, since no doctor can be called.
export function headline(dateText, bodyLevel, psycheLevel, { bodyFresh = true, mindFresh = true, shipLevel = LEVEL.FINE, doctorReachable = true } = {}) {
  const ship = shipLevel >= LEVEL.URGENT ? 'Ship emergency: follow ship procedures. '
    : shipLevel >= LEVEL.ACTION ? 'Ship caution: follow ship procedures. ' : '';
  const word = (lv) => (lv === LEVEL.URGENT ? (doctorReachable ? 'needs help: a doctor has been called' : 'needs help: the crew on board has been alerted')
    : lv === LEVEL.ACTION ? 'needs action'
      : lv === LEVEL.ATTENTION ? 'needs attention' : 'is excellent');
  const at = `${ship}As of ${dateText}, `;
  const bodyKnown = bodyLevel > LEVEL.FINE || bodyFresh;
  const mindKnown = psycheLevel > LEVEL.FINE || mindFresh;
  if (bodyKnown && mindKnown) {
    if (bodyLevel === LEVEL.FINE && psycheLevel === LEVEL.FINE) {
      return `${at}your physical and mental condition is excellent.${ship ? '' : ' Keep it up, well done!'}`;
    }
    if (bodyLevel >= psycheLevel) return `${at}your physical condition ${word(bodyLevel)}, your mental condition ${word(psycheLevel)}.`;
    return `${at}your mental condition ${word(psycheLevel)}, your physical condition ${word(bodyLevel)}.`;
  }
  if (!bodyKnown && !mindKnown) return `${at}there is not enough fresh data to judge your physical and mental condition.`;
  // One side cannot be judged: a problem on the other side comes first, missing data comes before "excellent".
  const [knownSide, knownLevel, unknownSide] = bodyKnown ? ['physical', bodyLevel, 'mental'] : ['mental', psycheLevel, 'physical'];
  const unknown = `there is not enough fresh data to judge your ${unknownSide} condition`;
  const known = `your ${knownSide} condition ${word(knownLevel)}`;
  return knownLevel > LEVEL.FINE ? `${at}${known}, ${unknown}.` : `${at}${unknown}, ${known}.`;
}

// The message for one person's assessment, with every variant above.
export function headlineFor(dateText, a) {
  return headline(dateText, a.body.level, a.psyche.level, {
    bodyFresh: !a.fresh || a.fresh.body,
    mindFresh: !a.fresh || a.fresh.mind,
    shipLevel: a.ship ? a.ship.level : LEVEL.FINE,
    doctorReachable: a.doctorReachable !== false,
  });
}
